class TimingProxy : DispatchProxy
{
    protected override object? Invoke(MethodInfo? method, object?[]? args)
    {
        var sw = Stopwatch.StartNew();
        try { return method!.Invoke(target, args); }
        finally { metrics.Record(method.Name, sw.Elapsed); }
    }
}
var payments = DispatchProxy.Create<IPaymentService, TimingProxy>();
